// Recuerda entre ejecuciones qué turnos ya se enviaron.
// (La memoria se guarda solo cuando el flujo está ACTIVO, no en pruebas manuales.)
const estado = $getWorkflowStaticData('global');
const enviados = new Set(estado.enviados ?? []);

// Límite de correos de la demostración (LIMITE_CORREOS_DEMO en .env).
// 5 por defecto; 0 = sin límite (se envían todos los turnos).
const valor = parseInt($env.LIMITE_CORREOS_DEMO ?? '5', 10);
const limite = Number.isNaN(valor) ? 5 : valor;
if (limite > 0 && enviados.size >= limite) {
  return [];
}

// El CSV ya viene ordenado por fecha y turno: tomamos el primero que no se haya enviado.
const siguiente = $input.all().find((item) => !enviados.has(item.json.id_envio));

// Si ya se enviaron todos, el flujo termina aquí sin mandar correo.
return siguiente ? [siguiente] : [];

// Solo se llega aquí si el correo se envió bien: se anota el turno como enviado.
// Si el envío falla, no se anota y se reintenta en el siguiente minuto.
const estado = $getWorkflowStaticData('global');
estado.enviados = estado.enviados ?? [];
const idEnvio = $('Elegir siguiente turno').first().json.id_envio;
estado.enviados.push(idEnvio);
return [{ json: { id_envio: idEnvio, correos_enviados: estado.enviados.length } }];
